// worktreeSettingsPaths resolves the base and local settings file paths under
// an explicit worktree root.
func worktreeSettingsPaths(worktreeRoot string) (base, local string) {
	return filepath.Join(worktreeRoot, EntireSettingsFile), filepath.Join(worktreeRoot, EntireSettingsLocalFile)
}

// LoadForWorktreeRoot is Load for an explicit worktree root instead of the
// process working directory. Code that already holds a repository — a doctor
// repair, a test fixture — must read that repository's settings, not whatever
// the current directory happens to be inside.
func LoadForWorktreeRoot(ctx context.Context, worktreeRoot string) (*EntireSettings, error) {
	return loadForWorktreeRoot(ctx, worktreeRoot)
}

func loadForWorktreeRoot(ctx context.Context, worktreeRoot string) (*EntireSettings, error) {
	return loadForWorktreeRootWithAgentPolicy(ctx, worktreeRoot, true)
}

func loadForWorktreeRootWithAgentPolicy(ctx context.Context, worktreeRoot string, installAgentPolicy bool) (*EntireSettings, error) {
	settingsFileAbs, localSettingsFileAbs := worktreeSettingsPaths(worktreeRoot)
	preferencesFileAbs := ""
	if path, prefErr := clonePreferencesPathForWorktreeRoot(ctx, worktreeRoot); prefErr == nil {
		preferencesFileAbs = path
	} else {
		logging.Debug(ctx, "clone preferences path unresolved; skipping preferences layer",
			slog.String("error", prefErr.Error()))
	}
	return loadMergedSettingsWithAgentPolicy(ctx, settingsFileAbs, preferencesFileAbs, localSettingsFileAbs, installAgentPolicy)
}

func clonePreferencesPathForWorktreeRoot(ctx context.Context, worktreeRoot string) (string, error) {
	cmd := exec.CommandContext(ctx, "git", "-C", worktreeRoot, "rev-parse", "--git-common-dir")
	output, err := cmd.Output()
	if err != nil {
		return "", fmt.Errorf("resolve git common dir: %w", err)
	}

	commonDir := strings.TrimSpace(string(output))
	if !filepath.IsAbs(commonDir) {
		commonDir = filepath.Join(worktreeRoot, commonDir)
	}
	return filepath.Join(filepath.Clean(commonDir), ClonePreferencesFile), nil
}

// worktreeRootOfSettingsFile recovers the worktree root a settings path was
// built from: settingsAbsPaths joins <root>/.entire/<file>, so the root is two
// levels up. Used only as the KEY the vouched-symlink policy is scoped by, never
// as a base for I/O, so the derived-path rule in CLAUDE.md does not apply -- an
// inconsistent key costs a refused symlink, which is the safe direction.
func worktreeRootOfSettingsFile(settingsFileAbs string) string {
	if settingsFileAbs == "" {
		return ""
	}
	return filepath.Dir(filepath.Dir(settingsFileAbs))
}

func loadMergedSettings(ctx context.Context, settingsFileAbs, preferencesFileAbs, localSettingsFileAbs string) (*EntireSettings, error) {
	return loadMergedSettingsWithAgentPolicy(ctx, settingsFileAbs, preferencesFileAbs, localSettingsFileAbs, true)
}

func loadMergedSettingsWithAgentPolicy(
	ctx context.Context,
	settingsFileAbs, preferencesFileAbs, localSettingsFileAbs string,
	installAgentPolicy bool,
) (*EntireSettings, error) {
	// Load base settings
	settings, err := loadFromFile(settingsFileAbs)
	if err != nil {
		return nil, fmt.Errorf("reading settings file: %w", err)
	}

	var preferences *ClonePreferences
	if preferencesFileAbs != "" {
		preferences, err = loadClonePreferencesFromFile(preferencesFileAbs)
		if err != nil {
			return nil, fmt.Errorf("reading clone preferences file: %w", err)
		}
		applyClonePreferences(settings, preferences)
	}

	// Apply local overrides if they exist — but only from a file that is
	// genuinely local. See localLayerTrackedReason.
	localData, err := readConfined(localSettingsFileAbs)
	if err != nil {
		if !errors.Is(err, fs.ErrNotExist) {
			return nil, fmt.Errorf("reading local settings file: %w", err)
		}
		// Local file doesn't exist, continue without overrides
	} else if classifyLocalSettings(ctx, localSettingsFileAbs) == localTracked {
		// Dropped only on PROOF that the file is tracked. Discarding every
		// local setting because a repository could not be read would be a
		// worse failure than the one being guarded against — the exec-bearing
		// OPF command applies the stricter policy for itself.
		settings.localLayerRejection = localLayerTrackedReason
		localData = nil
	} else if err := mergeJSON(settings, localData); err != nil {
		return nil, fmt.Errorf("merging local settings: %w", err)
	}

	// openai_privacy_filter.command is executed, so it is honored only from a
	// local file positively verified as this developer's own. external_agents
	// grants execution of every entire-agent-* binary on $PATH, so it gets the
	// same gate. Agent instruction fields (investigate.always_prompt, review
	// prompts) are appended verbatim to prompts of agents spawned with
	// approval checks disabled, so they get the same provenance requirement,
	// with clone-local preferences as an additional trusted layer.
	enforceOPFCommandTrust(ctx, settings, localSettingsFileAbs, localData)
	enforceExternalAgentsTrust(ctx, settings, localSettingsFileAbs, localData)
	enforceAgentPromptTrust(ctx, settings, localSettingsFileAbs, localData, preferences)
	// allow_symlinked_agent_dirs decides where Entire writes an agent's hook
	// config, so it gets the same gate, and then installs the surviving set as
	// the process-wide policy.
	enforceSymlinkedAgentDirsTrust(ctx, settings, localSettingsFileAbs, localData)
	if installAgentPolicy {
		applyVouchedAgentDirs(settings, worktreeRootOfSettingsFile(settingsFileAbs))
	}

	// Re-validate after merge. Individual files are validated by loadFromFile,
	// but mergeJSON patches fields independently and can produce combinations
	// (e.g. model without provider when the local override sets only a model
	// on top of a base with no provider) that neither file alone contained.
	if err := settings.SummaryGeneration.Validate(); err != nil {
		return nil, fmt.Errorf("merged settings invalid: %w", err)
	}

	if err := validateScannerSettings(settings); err != nil {
		return nil, fmt.Errorf("merged settings invalid: %w", err)
	}

	return settings, nil
}

// LoadFromFile loads settings from a specific file path without merging local overrides.
// Returns default settings if the file doesn't exist.
// Use this when you need to display individual settings files separately.
func LoadFromFile(filePath string) (*EntireSettings, error) {
	return loadFromFile(filePath)
}

}

// mergeStringMap unmarshals raw into a string map and merges it into dst,
// adopting the parsed map wholesale when dst is nil. field names the setting
// in parse errors.
func mergeStringMap(dst *map[string]string, raw json.RawMessage, field string) error {
	var m map[string]string
	if err := json.Unmarshal(raw, &m); err != nil {
		return fmt.Errorf("parsing %s: %w", field, err)
	}
	if *dst == nil {
		*dst = m
		return nil
	}
	for k, v := range m {
		(*dst)[k] = v
	}
	return nil
}

// IsSetUp returns true if Entire has been set up in the current repository.
// This checks if .entire/settings.json exists.
// Use this to avoid creating files/directories in repos where Entire was never enabled.
func IsSetUp(ctx context.Context) bool {
	return entireFileExists(ctx, SettingsName)
}

// FilesPresent reports whether each settings file exists, keeping an access
// failure distinct from absence. IsSetUp and IsSetUpLocal collapse both into
// false, which is right for a gate but wrong for `entire status`, whose whole
// job is to say why it cannot see something.
func FilesPresent(ctx context.Context) (project, local bool, err error) {
	root, err := entiredir.OpenForRead(ctx)
	return filesPresent(root, err)
}

// FilesPresentForWorktreeRoot is FilesPresent for an explicit worktree root.
func FilesPresentForWorktreeRoot(worktreeRoot string) (project, local bool, err error) {
	root, err := entiredir.OpenAtForRead(worktreeRoot)
	return filesPresent(root, err)
}

func filesPresent(root *os.Root, openErr error) (project, local bool, err error) {
	err = openErr
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return false, false, nil
		}
		return false, false, fmt.Errorf("cannot access %s: %w", paths.EntireDir, err)
	}
	project, err = fileExists(root, SettingsName)
	if err != nil {
		return false, false, fmt.Errorf("cannot access project settings file: %w", err)
	}
	local, err = fileExists(root, SettingsLocalName)
	if err != nil {
		return false, false, fmt.Errorf("cannot access local settings file: %w", err)
	}
	return project, local, nil
}

func fileExists(root *os.Root, name string) (bool, error) {
	if _, err := root.Lstat(name); err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return false, nil
		}
		return false, err //nolint:wrapcheck // caller names the file
	}
	return true, nil
}

// IsSetUpLocal returns true if .entire/settings.local.json exists. Callers that
// pick a write target need the two scopes separately, which IsSetUpAny folds
// together.
func IsSetUpLocal(ctx context.Context) bool {
	return entireFileExists(ctx, SettingsLocalName)
}

// IsSetUpAny returns true if Entire has been set up in the current repository,
// checking both .entire/settings.json and .entire/settings.local.json.
// Use this to detect any prior setup, even if only local settings exist.
func IsSetUpAny(ctx context.Context) bool {
	return IsSetUp(ctx) || IsSetUpLocal(ctx)
}

// entireFileExists reports whether name exists directly under .entire. Lstat,
// not Stat: a settings file that is a dangling symlink still counts as "set up"
// here, exactly as it did before, and the root refuses to follow one out of
// .entire regardless.
func entireFileExists(ctx context.Context, name string) bool {
	root, err := entiredir.OpenForRead(ctx)
	if err != nil {
		return false
	}
	_, err = root.Lstat(name)
	return err == nil
}

// IsSetUpAndEnabled returns true if Entire is both set up and enabled.
// "Set up" spans either scope — .entire/settings.json OR
// .entire/settings.local.json — so it must check IsSetUpAny, not IsSetUp.
// `entire enable --local` writes only settings.local.json and never creates the
// base file; gating on the base file alone would treat such a local-only repo
// as inactive and make every hook a silent no-op, dropping all checkpoint
// capture for that documented workflow. The IsSetUpAny guard is still required
// so a never-enabled repo (no settings file in any scope) is not treated as
// enabled by Load's default Enabled: true. Any settings read error is treated
// as disabled (fail closed).
// Use this for hooks that should be no-ops when Entire is not active.
func IsSetUpAndEnabled(ctx context.Context) bool {
	if !IsSetUpAny(ctx) {
		return false
	}
	s, err := Load(ctx)
	if err != nil {
		return false
	}
	return s.Enabled
}

// IsSetUpAndEnabledForWorktreeRoot is a read-only IsSetUpAndEnabled for an
// explicit worktree root. It does not install that worktree's agent-directory
// policy into the process.
func IsSetUpAndEnabledForWorktreeRoot(ctx context.Context, worktreeRoot string) bool {
	project, local, err := FilesPresentForWorktreeRoot(worktreeRoot)
	if err != nil || (!project && !local) {
		return false
	}
	// This is an inspection of another worktree. Loading its effective settings
	// must not replace the current worktree's process-wide agent-directory policy.
	s, err := loadForWorktreeRootWithAgentPolicy(ctx, worktreeRoot, false)
	if err != nil {
		return false
	}
	return s.Enabled
}

// ProjectSettingsEnabledForWorktreeRoot reports whether an explicit worktree
// has an enabled project settings layer, without consulting local overrides.
func ProjectSettingsEnabledForWorktreeRoot(worktreeRoot string) bool {
	project, _, err := FilesPresentForWorktreeRoot(worktreeRoot)
	if err != nil || !project {
		return false
	}
	s, err := loadFromFile(filepath.Join(worktreeRoot, EntireSettingsFile))
	return err == nil && s.Enabled
// Package entiredir owns access to the repository's .entire directory.
//
// Every non-test read and write under .entire goes through the single *os.Root
// this package hands out, rather than through an absolute path assembled by the
// caller. Two properties follow from that, and neither survives if a call site
// reverts to os.ReadFile/os.WriteFile on a joined path:
//
//   - Containment. .entire holds paths named from agent-supplied session IDs,
//     tool-use IDs, and tree paths. A root confines every open to the directory
//     at the kernel level, so a crafted name cannot escape it, and a symlink
//     swapped in between resolution and open (TOCTOU) surfaces as an error
//     rather than a redirected write.
//   - One directory handle per worktree. The root is opened once and memoized,
//     so the hot hook paths stop paying an OpenRoot per state file, and every
//     consumer observes the same directory even if .entire is renamed or
//     replaced underneath a long-running process.
//
// Creation is deliberately lazy and split across two entry points. Open creates
// .entire because its callers are about to write; OpenForRead never creates,
// because a command that only looks must leave an untouched repo untouched.
// That distinction is load-bearing for logging in particular: the log file is
// created by the first line actually written, so a command that logs nothing
// (completion, version, help) must not leave an .entire behind.
//
// Reset exists for the paths that delete the directory (entire disable,
// entire clean) and for tests. A cached root that outlives its directory is a
// handle to an unlinked inode: writes through it succeed and land nowhere.
package entiredir

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/osroot"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// dirPerm is the mode .entire is created with. It matches the mode the
// directory already had when each consumer created its own subdirectory.
const dirPerm = 0o750

// ReadFile reads an Entire-owned file without following a symlink at the leaf.
func ReadFile(root *os.Root, name string) ([]byte, error) {
	return osroot.ReadFileNoFollow(root, name) //nolint:wrapcheck // preserve os error classification
}

// WriteFile atomically replaces an Entire-owned file. Renaming a newly-created
// temporary file over name replaces a planted leaf symlink rather than opening
// and truncating its target.
func WriteFile(root *os.Root, name string, data []byte, perm os.FileMode) error {
	return jsonutil.WriteFileAtomicIn(root, name, data, perm) //nolint:wrapcheck // caller supplies path context
}

// Open returns the shared *os.Root for the current worktree's .entire
// directory, creating the directory if it does not exist. Use it from write
// paths; read-only callers want OpenForRead.
//
// The returned root is owned by this package and shared with every other
// caller. Do not close it.
func Open(ctx context.Context) (*os.Root, error) {
	worktreeRoot, err := anchor(ctx)
	if err != nil {
		return nil, err
	}
	return OpenAt(worktreeRoot)
}

// OpenForRead is Open without creating .entire. A missing directory is
// reported as fs.ErrNotExist, which callers classify with errors.Is.
func OpenForRead(ctx context.Context) (*os.Root, error) {
	worktreeRoot, err := anchor(ctx)
	if err != nil {
		return nil, err
	}
	return OpenAtForRead(worktreeRoot)
}

// OpenAt is Open for an explicit worktree root, for the callers that already
// resolved one (or that act on a worktree other than the current directory).
func OpenAt(worktreeRoot string) (*os.Root, error) {
	return open(worktreeRoot, true)
}

// OpenAtForRead is OpenForRead for an explicit worktree root.
func OpenAtForRead(worktreeRoot string) (*os.Root, error) {
	return open(worktreeRoot, false)
}

// Opener returns a thunk that calls Open when invoked, for consumers that are
// handed their storage up front but must not touch the disk until they first
// write (see logging.Config.Root).
func Opener(ctx context.Context) func() (*os.Root, error) {
	return func() (*os.Root, error) { return Open(ctx) }
}

// OpenerAt returns a thunk that calls OpenAt when invoked.
func OpenerAt(worktreeRoot string) func() (*os.Root, error) {
	return func() (*os.Root, error) { return OpenAt(worktreeRoot) }
}

// Path returns the absolute path of the current worktree's .entire directory.
// It is for messages and for the few consumers that must hand a path to an
// external process; it is not an invitation to do I/O on the result.
func Path(ctx context.Context) (string, error) {
	worktreeRoot, err := anchor(ctx)
	if err != nil {
		return "", err
	}
	return filepath.Join(worktreeRoot, paths.EntireDir), nil
}

// Reset closes and forgets every cached root. Call it after deleting .entire:
// a root cached across the deletion refers to an unlinked directory, so writes
// through it succeed and land nowhere.
//
// The registry is shared with the other anchors, so this clears them too. That
// is the behaviour teardown wants — a repo whose .entire just went away is not a
// repo whose .git root is worth keeping — and tests get one reset to call.
func Reset() {
	osroot.ResetShared()
}

// Name converts a repo-relative path under .entire (for example
// paths.EntireTmpDir) to a name relative to the .entire root. The repo-relative
// constants stay as they are because git paths, settings display, and gitignore
// entries all need them; this is the one-line bridge to root-relative I/O.
//
// A path outside .entire is an error rather than a silent passthrough: the
// alternative is a name that resolves inside .entire but means something else.
func Name(repoRelPath string) (string, error) {
	cleaned := filepath.ToSlash(filepath.Clean(filepath.FromSlash(repoRelPath)))
	if cleaned == paths.EntireDir {
		return ".", nil
	}
	rest, ok := strings.CutPrefix(cleaned, paths.EntireDir+"/")
	if !ok || rest == "" {
		return "", fmt.Errorf("%q is not under %s", repoRelPath, paths.EntireDir)
	}
	return rest, nil
}

// MustName is Name for package-level constants that are known to be under
// .entire. It panics on a path that is not, which can only be a programming
// error in a literal.
func MustName(repoRelPath string) string {
	name, err := Name(repoRelPath)
	if err != nil {
		panic(err)
	}
	return name
}

// anchor resolves the directory .entire sits in: the git worktree root, falling
// back to the current directory only on git's positive "not a repository"
// verdict.
//
// The fallback is load-bearing — `entire enable` runs in a directory that is not
// a repository yet — and gating it on paths.ErrNotARepository is what keeps it
// narrow. That sentinel means git ran and said there is no repository here.
// Every other failure (git off $PATH, a cancelled context, dubious ownership, a
// permission error, malformed output) means "we could not find out", and
// answering that with the current directory is how the paths.AbsPath fallback
// this replaces used to give an agent working in a subdirectory of a real repo
// its own .entire beside itself. A root is only as trustworthy as the directory
// it is opened on, so a base this function is not sure about is not a base it
// hands back.
//
// Callers that name a worktree themselves use OpenAt and never reach this.
func anchor(ctx context.Context) (string, error) {
	worktreeRoot, err := paths.WorktreeRoot(ctx)
	switch {
	case err == nil:
		return worktreeRoot, nil
	case !errors.Is(err, paths.ErrNotARepository):
		return "", fmt.Errorf("resolve %s location: %w", paths.EntireDir, err)
	}

	cwd, cwdErr := os.Getwd() //nolint:forbidigo // no repository here; see the doc comment
	if cwdErr != nil {
		return "", fmt.Errorf("resolve %s location: %w", paths.EntireDir, cwdErr)
	}
	return cwd, nil
}

// PathTo returns the absolute path of repoRelPath, which must name something
// under .entire. It exists for the consumers that carry an absolute path in
// their own API — settings resolves one per layer and hands it back to callers
// that print it — so those resolve through this package's anchor rather than
// paths.AbsPath, whose relative fallback is the thing anchor exists to avoid.
func PathTo(ctx context.Context, repoRelPath string) (string, error) {
	if _, err := Name(repoRelPath); err != nil {
		return "", err
	}
	worktreeRoot, err := anchor(ctx)
	if err != nil {
		return "", err
	}
	return filepath.Join(worktreeRoot, filepath.FromSlash(repoRelPath)), nil
}

func open(worktreeRoot string, create bool) (*os.Root, error) {
	if worktreeRoot == "" {
		return nil, errors.New("entiredir: worktree root is required")
	}
	abs, err := filepath.Abs(worktreeRoot)
	if err != nil {
		return nil, fmt.Errorf("resolve %s: %w", worktreeRoot, err)
	}
	return openDir(filepath.Join(abs, paths.EntireDir), create)
}

// openDir is the one place a *os.Root over a .entire directory is created. Every
// entry point funnels here so the create/no-create split stays in a single
// branch; osroot.Shared owns the open-at-most-once part.
func openDir(dir string, create bool) (*os.Root, error) {
	parentDir := filepath.Dir(dir)
	name := filepath.Base(dir)
	parent, err := osroot.Shared(parentDir)
	if err != nil {
		return nil, err //nolint:wrapcheck // Shared names the directory, and returns a missing one unwrapped for errors.Is
	}
	if create {
		if err := osroot.MkdirAllNoSymlink(parent, name, dirPerm); err != nil {
			return nil, fmt.Errorf("create %s: %w", dir, err)
		}
package agent

import (
	"fmt"
	"os"
	"path"
	"path/filepath"

	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/osroot"
	"github.com/entireio/cli/cmd/entire/cli/worktreedir"
)

// HookConfigFile is an agent's hook-configuration file inside the worktree —
// .claude/settings.json, .cursor/hooks.json, .gemini/settings.json,
// .github/hooks/entire.json, .factory/settings.json, .codex/hooks.json,
// .opencode/plugins/entire.ts, .pi/extensions/entire/index.ts.
//
// Eight agents each carried the same four lines: filepath.Join a repo root with
// a fixed relative path, then os.ReadFile / os.MkdirAll / os.WriteFile /
// os.Remove on the result, each with a //nolint:gosec saying the path came from
// the repo root. That justification is about where the path was BUILT and says
// nothing about where it RESOLVES, which is the part that matters: `.claude` and
// its siblings live in the working tree, and a working tree arrives by clone.
// A repository carrying a checked-in symlink at `.claude` therefore had
// `entire enable` create directories and write JSON through it, to wherever it
// pointed — outside the repository included.
//
// Anchoring on worktreedir fixes that at the root rather than at each call site:
// the base is the worktree root, the agent's fixed subpath is a NAME inside it,
// and directories are created with MkdirAllNoSymlink so a symlinked component is
// refused by name instead of silently followed. It also collapses the eight
// copies into one, which is what keeps the next agent integration from
// reintroducing the pattern. Pi was the one that got left behind on the first
// pass and had to be migrated afterwards, which is the argument for routing a
// new agent through here rather than for trusting that someone will notice.
//
// Every symlink component is refused, including the file itself. os.Root blocks
// a link that escapes the worktree but follows one pointing elsewhere inside
// it; accepting the leaf would let `.claude/settings.json -> ../victim.json`
// redirect both the merge read and the subsequent write.
//
// An earlier revision of this type deliberately allowed a symlinked leaf, on the
// grounds that pointing `.claude/settings.json` at a dotfile repo is a real
// setup Entire has no business breaking. That was reconsidered, and the reason
// is worth keeping: the merge READ pulls the target's contents into what Entire
// then writes, and the write is a rename, which replaces the user's link with a
// regular file rather than following it. Both happen silently. Refusing is the
// legible version of the same outcome.
//
// The setup still works, because the thing that makes a link dangerous here is
// that it arrived with the checkout. A developer who wants one keeps it out of
// the repository — `git rm --cached .claude/settings.json` and a .gitignore
// entry — and manages it locally, which is what a dotfile workflow does anyway.
type HookConfigFile struct {
	root *os.Root
	// name is root-relative, for I/O. It is NOT worktree-relative: when a
	// vouched symlinked agent directory was followed, the root is anchored at
	// that directory's target and name has lost the components consumed getting
	// there.
	name string
	// relName is the worktree-relative name, for every DECISION about the path
	// as opposed to every access through it. Two coordinates for one file, the
	// same split entiredir.Name draws, and RemoveDir is why it exists: it
	// reasons about which directory it is allowed to delete, and doing that on
	// the root-relative name let anchoring change the answer.
	relName string
	path    string
}

// HookConfigLocator is implemented by an agent whose Entire hook configuration
// is a file inside the worktree: it returns the same worktree-relative,
// slash-separated path the agent passes to OpenHookConfig.
//
// It exists for the callers that must reason about that path WITHOUT doing I/O
// on it. Doctor's symlink diagnosis is the first: the directories BETWEEN an
// agent's own directory and its config file — `.pi/extensions`,
// `.pi/extensions/entire`, `.opencode/plugins` — are created by Entire and
// appear in no other registry, because ProtectedDirs names what the AGENT owns
// (`.pi`, `.opencode`) and stops there. Deriving them from a hand-kept list in
// the caller is how two of them came to be unchecked in the first place.
//
// Optional: an agent whose hooks are not a worktree file (an external plugin
// declaring them in its manifest) does not implement it. See
// TestAllHookConfigRelPaths_CoversEveryWorktreeConfigAgent for the ones that
// must.
type HookConfigLocator interface {
	// HookConfigRelPath returns the config file's path relative to the worktree
	// root, slash-separated, exactly as passed to OpenHookConfig.
	HookConfigRelPath() string
}

// OpenHookConfig returns the hook-config file at relPath inside worktreeRoot.
//
// relPath is slash-separated and relative to the worktree root
// (".cursor/hooks.json"). The directory does not need to exist: Read reports a
// missing file the way os.ReadFile does, and Write creates the parents.
func OpenHookConfig(worktreeRoot, relPath string) (*HookConfigFile, error) {
	// Validate against the worktree root first, so a relPath that escapes is
	// rejected before anything is resolved. AnchorWorktreePath re-anchors only
	// on directories the user vouched for by name, but it should never be the
	// thing deciding whether the path was well formed.
	name, err := worktreedir.Name(worktreeRoot, relPath)
	if err != nil {
		return nil, fmt.Errorf("resolve hook config path: %w", err)
	}
	display := filepath.Join(worktreeRoot, filepath.FromSlash(name))

	// Two bases, one behaviour below. The ordinary case anchors on the worktree
	// root and every agent directory stays a name inside it, refusable by
	// MkdirAllNoSymlink. A vouched symlinked directory anchors on its resolved
	// target instead, and everything below it is still a name inside a root.
	root, inner, err := OpenAnchoredRoot(worktreeRoot, name)
	if err != nil {
		return nil, fmt.Errorf("resolve hook config path: %w", err)
	}
	return &HookConfigFile{
		root:    root,
		name:    inner,
		relName: name,
		// The link's own path, not the resolved one. It is what the user typed,
		// what doctor prints, and what the agents write into their own config,
		// where following the link is the agent's business and works.
		path: display,
	}, nil
}

// Path is the file's absolute path, for messages and for the agent config that
// has to name it. It is not an invitation to do I/O on the result.
func (f *HookConfigFile) Path() string { return f.path }

// Read returns the file's contents. A missing file is reported unwrapped so
// callers can classify it with os.IsNotExist, which is how every agent's
// install path decides between "merge into existing" and "write fresh".
func (f *HookConfigFile) Read() ([]byte, error) {
	return osroot.ReadFileNoFollow(f.root, f.name) //nolint:wrapcheck // see doc comment
}

// Exists reports whether the file is present at a path Entire will read.
//
// A symlinked parent directory counts as absent rather than as an error, since
// the signature has nowhere to put one. That is the useful answer: every caller
// uses this to choose between merging into an existing file and writing a fresh
// one, and Write refuses the same path with a message that names the link.
func (f *HookConfigFile) Exists() bool {
	info, err := osroot.LstatNoSymlinks(f.root, f.name)
	return err == nil && info.Mode()&os.ModeSymlink == 0
}

// Write writes data, creating parent directories. A parent that already exists
// as a symlink is refused with osroot.ErrSymlinkedPath rather than followed.
func (f *HookConfigFile) Write(data []byte, perm os.FileMode) error {
	if dir := path.Dir(f.name); dir != "." {
		// 0750 for every agent, including the directories Entire creates below
		// an agent's own (.pi/extensions/entire). The agent process runs as
		// whoever ran `entire enable`, so it can traverse its own config
		// directory; a setup where those differ (provisioned as root, agent as
		// another uid) needs 0755 for all nine and is not one agent's to choose.
		if err := osroot.MkdirAllNoSymlink(f.root, dir, 0o750); err != nil {
			return fmt.Errorf("create %s: %w", filepath.Dir(f.path), err)
		}
	}
	if info, err := osroot.LstatNoSymlinks(f.root, f.name); err == nil && info.Mode()&os.ModeSymlink != 0 {
		return fmt.Errorf("write %s: %w", f.path, osroot.ErrSymlinkedPath)
	} else if err != nil && !os.IsNotExist(err) {
		return fmt.Errorf("write %s: %w", f.path, err)
	}
	if err := jsonutil.WriteFileAtomicIn(f.root, f.name, data, perm); err != nil {
		return fmt.Errorf("write %s: %w", f.path, err)
	}
	return nil
}

// Remove deletes the file. A file that is not there is not an error; a
// symlinked parent directory is, because the file this would delete is at the
// far end of a link Entire did not create.
func (f *HookConfigFile) Remove() error {
	if err := osroot.RemoveNoSymlinks(f.root, f.name); err != nil {
		return fmt.Errorf("remove %s: %w", f.path, err)
	}
	return nil
}

// RemoveDir deletes the directory the file lives in, and everything in it,
// refusing a symlink at any component along the way.
//
// One agent needs this, and it is not a general uninstall: Pi's whole
// integration is `.pi/extensions/entire/index.ts`, a directory that exists only
// to hold that one file, and pi discovers extensions BY DIRECTORY — so removing
// the file alone leaves an empty `.pi/extensions/entire` for pi to find and
// nothing to load from it. Every other agent writes into a directory the agent
