   440	func loadClaudeSettingsFromConfig(ctx context.Context, cfg *agent.HookConfigFile) (ClaudeSettings, error) {
   441		data, err := cfg.Read()
   442		// No settings file means no hooks, which is an answer; anything else means we
   443		// could not read the answer.
   444		if errors.Is(err, os.ErrNotExist) {
   445			return ClaudeSettings{}, nil
   446		}
   447		if err != nil {
   448			logging.Warn(ctx, "claude-code: failed to read settings file", "path", cfg.Path(), "err", err)
   449			return ClaudeSettings{}, fmt.Errorf("read %s: %w", cfg.Path(), err)
   450		}
   451	
   452		var settings ClaudeSettings
   453		if err := json.Unmarshal(data, &settings); err != nil {
   454			logging.Warn(ctx, "claude-code: failed to parse settings file", "path", cfg.Path(), "err", err)
   455			return ClaudeSettings{}, fmt.Errorf("parse %s: %w", cfg.Path(), err)
   456		}
   457		return settings, nil
   458	}
