   747	func loadMergedSettingsWithAgentPolicy(
   748		ctx context.Context,
   749		settingsFileAbs, preferencesFileAbs, localSettingsFileAbs string,
   750		installAgentPolicy bool,
   751	) (*EntireSettings, error) {
   752		// Load base settings
   753		settings, err := loadFromFile(settingsFileAbs)
   754		if err != nil {
   755			return nil, fmt.Errorf("reading settings file: %w", err)
   756		}
   757	
   758		var preferences *ClonePreferences
   759		if preferencesFileAbs != "" {
   760			preferences, err = loadClonePreferencesFromFile(preferencesFileAbs)
   761			if err != nil {
   762				return nil, fmt.Errorf("reading clone preferences file: %w", err)
   763			}
   764			applyClonePreferences(settings, preferences)
   765		}
   766	
   767		// Apply local overrides if they exist — but only from a file that is
   768		// genuinely local. See localLayerTrackedReason.
   769		localData, err := readConfined(localSettingsFileAbs)
   770		if err != nil {
   771			if !errors.Is(err, fs.ErrNotExist) {
   772				return nil, fmt.Errorf("reading local settings file: %w", err)
   773			}
   774			// Local file doesn't exist, continue without overrides
   775		} else if classifyLocalSettings(ctx, localSettingsFileAbs) == localTracked {
   776			// Dropped only on PROOF that the file is tracked. Discarding every
   777			// local setting because a repository could not be read would be a
   778			// worse failure than the one being guarded against — the exec-bearing
   779			// OPF command applies the stricter policy for itself.
   780			settings.localLayerRejection = localLayerTrackedReason
   781			localData = nil
   782		} else if err := mergeJSON(settings, localData); err != nil {
   783			return nil, fmt.Errorf("merging local settings: %w", err)
   784		}
   785	
   786		// openai_privacy_filter.command is executed, so it is honored only from a
   787		// local file positively verified as this developer's own. external_agents
   788		// grants execution of every entire-agent-* binary on $PATH, so it gets the
   789		// same gate. Agent instruction fields (investigate.always_prompt, review
   790		// prompts) are appended verbatim to prompts of agents spawned with
   791		// approval checks disabled, so they get the same provenance requirement,
   792		// with clone-local preferences as an additional trusted layer.
   793		enforceOPFCommandTrust(ctx, settings, localSettingsFileAbs, localData)
   794		enforceExternalAgentsTrust(ctx, settings, localSettingsFileAbs, localData)
   795		enforceAgentPromptTrust(ctx, settings, localSettingsFileAbs, localData, preferences)
   796		// allow_symlinked_agent_dirs decides where Entire writes an agent's hook
   797		// config, so it gets the same gate, and then installs the surviving set as
   798		// the process-wide policy.
   799		enforceSymlinkedAgentDirsTrust(ctx, settings, localSettingsFileAbs, localData)
   800		if installAgentPolicy {
   801			applyVouchedAgentDirs(settings, worktreeRootOfSettingsFile(settingsFileAbs))
   802		}
   803	
   804		// Re-validate after merge. Individual files are validated by loadFromFile,
   805		// but mergeJSON patches fields independently and can produce combinations
   806		// (e.g. model without provider when the local override sets only a model
   807		// on top of a base with no provider) that neither file alone contained.
   808		if err := settings.SummaryGeneration.Validate(); err != nil {
   809			return nil, fmt.Errorf("merged settings invalid: %w", err)
   810		}
   811	
   812		if err := validateScannerSettings(settings); err != nil {
   813			return nil, fmt.Errorf("merged settings invalid: %w", err)
   814		}
