  1858	// IsSetUpAndEnabled returns true if Entire is both set up and enabled.
  1859	// "Set up" spans either scope — .entire/settings.json OR
  1860	// .entire/settings.local.json — so it must check IsSetUpAny, not IsSetUp.
  1861	// `entire enable --local` writes only settings.local.json and never creates the
  1862	// base file; gating on the base file alone would treat such a local-only repo
  1863	// as inactive and make every hook a silent no-op, dropping all checkpoint
  1864	// capture for that documented workflow. The IsSetUpAny guard is still required
  1865	// so a never-enabled repo (no settings file in any scope) is not treated as
  1866	// enabled by Load's default Enabled: true. Any settings read error is treated
  1867	// as disabled (fail closed).
  1868	// Use this for hooks that should be no-ops when Entire is not active.
  1869	func IsSetUpAndEnabled(ctx context.Context) bool {
  1870		if !IsSetUpAny(ctx) {
  1871			return false
  1872		}
  1873		s, err := Load(ctx)
  1874		if err != nil {
  1875			return false
  1876		}
  1877		return s.Enabled
  1878	}
