   653	// Unlike the agent hook checks this one repairs rather than only warning: the
   654	// reinstall is content-idempotent, backs up any foreign hook it displaces, and
   655	// writes exactly what the next turn-start would write anyway. Someone reaching
   656	// for doctor after a rejected push wants to be unblocked, not handed a second
   657	// command to run.
   658	func checkGitHooksWithWorktreeSetup(cmd *cobra.Command, force bool, setupIssue *worktreeSetupIssue) error {
   659		ctx := cmd.Context()
   660		w := cmd.OutOrStdout()
   661	
   662		switch strategy.CheckGitHookState(ctx) {
   663		case strategy.GitHooksCurrent:
   664			if setupIssue != nil && setupIssue.CurrentCaptureInactive {
   665				fmt.Fprintln(w, "Git hooks: INSTALLED BUT INACTIVE")
   666				fmt.Fprintln(w, "  This worktree has no Entire settings, so its hooks skip checkpoint capture.")
   667				return nil
   668			}
   669			fmt.Fprintln(w, "✓ Git hooks: OK")
   670			return nil
   671	
   672		case strategy.GitHooksAbsent:
   673			// Missing hooks are only a problem where Entire was actually set up.
   674			// doctor runs in any git repo, so treating this as actionable would let
   675			// `entire doctor --force` install hooks into — and back up the existing
   676			// hooks of — a repo that never opted in. That is the loudest possible
   677			// surprise from a diagnostic command. The sibling checks already hold this
   678			// line: checkHookDrift stays silent on HooksAbsent, and
   679			// checkCodexHookTrust returns early when there is no codex hooks file.
   680			//
   681			// IsSetUpAny rather than IsSetUpAndEnabled: a repo that ran `entire
   682			// disable` still wants working hooks, because the hooks themselves are
   683			// what no-op while disabled.
   684			if !settings.IsSetUpAny(ctx) {
   685				return nil
   686			}
   687			fmt.Fprintln(w, "Git hooks: NOT INSTALLED")
   688			fmt.Fprintln(w, "  Commits in this repository are not captured as checkpoints.")
   689	
   690		case strategy.GitHooksOutdated:
   691			// Actionable whatever the settings say: a hook carrying Entire's marker
   692			// means this repo opted in at some point, and a stale one is actively
   693			// broken rather than merely missing.
   694			fmt.Fprintln(w, "Git hooks: OUT OF DATE")
   695			fmt.Fprintln(w, "  A hook still runs Entire from the working tree instead of the installed")
   696			fmt.Fprintln(w, "  binary. This can reject `git push`, because the path it names is gone.")
   697		}
