   126	// runStatusDetailed shows the effective status plus detailed status for each settings file.
   127	func runStatusDetailed(ctx context.Context, w io.Writer, sty statusStyles, settingsPath, localSettingsPath string, projectExists, localExists bool, setupIssue *worktreeSetupIssue) error {
